import { addDays, daysBetween } from '../helpers/dates.js';
import { listOverdueLoans } from '../reports/overdue.js';
import { composeNotice } from './compose.js';

/** Loans due within this many days get a reminder in the morning run. */
const DUE_SOON_DAYS = 2;

/** Returns the reminders of the morning run for loans that fall due within two days of today. */
export function dueSoonNotices(store, today) {
  const until = addDays(today, DUE_SOON_DAYS);
  return store
    .listAllLoans()
    .filter((loan) => loan.returnedOn === null && loan.dueOn >= today && loan.dueOn <= until)
    .map((loan) => noticeFor(store, 'dueSoon', loan));
}

/** Returns the notices of the morning run for loans that are overdue today. */
export function overdueNotices(store, today) {
  return listOverdueLoans(store, today).map((loan) =>
    noticeFor(store, 'overdue', loan, { daysLate: lateBy(loan.dueOn, today) }),
  );
}

/** Words for how late a loan is, such as "1 day" or "5 days". */
function lateBy(dueOn, today) {
  const days = daysBetween(dueOn, today);
  return `${days} ${days === 1 ? 'day' : 'days'}`;
}

function noticeFor(store, kind, loan, extraValues = {}) {
  const member = store.getMember(loan.memberId);
  const item = store.getItem(loan.itemId);
  return composeNotice(kind, { member, values: { title: item.title, dueOn: loan.dueOn, ...extraValues } });
}
import assert from 'node:assert/strict';
import test from 'node:test';
import { composeNotice } from '../lib/notices/compose.js';
import { dueSoonNotices, overdueNotices } from '../lib/notices/digest.js';
import { ADA, BEN, BOOK, DVD, sampleLoan, sampleStore, TODAY } from './sample-library.js';

test('a notice by email goes to the email address, with a subject', () => {
  const notice = composeNotice('dueSoon', {
    member: ADA,
    values: { title: BOOK.title, dueOn: '2026-11-27' },
  });
  assert.equal(notice.channel, 'email');
  assert.equal(notice.to, ADA.email);
  assert.equal(notice.subject, 'An item is due soon');
  assert.match(notice.body, /^Hello Ada Okafor, "The Left Hand of Darkness" is due back on 2026-11-27\./);
});

test('a notice by text message goes to the phone number, greets by the preferred name and has no subject', () => {
  const notice = composeNotice('dueSoon', { member: BEN, values: { title: DVD.title, dueOn: '2026-11-27' } });
  assert.equal(notice.channel, 'sms');
  assert.equal(notice.to, BEN.phone);
  assert.equal(notice.subject, null);
  assert.match(notice.body, /^Hello Ben,/);
});

test('the morning run reminds members of loans due within two days, and of overdue loans', () => {
  const store = sampleStore({
    loans: [
      sampleLoan({ id: 'loan_1', item: BOOK, member: ADA, checkedOutOn: '2026-11-07', dueOn: '2026-11-28' }),
      sampleLoan({ id: 'loan_2', item: DVD, member: BEN, checkedOutOn: '2026-11-12', dueOn: '2026-11-19' }),
    ],
  });
  assert.deepEqual(
    dueSoonNotices(store, TODAY).map((notice) => notice.to),
    [ADA.email],
  );
  assert.deepEqual(
    overdueNotices(store, TODAY).map((notice) => notice.to),
    [BEN.phone],
  );
});

test('an overdue notice says how many days late the item is', () => {
  const store = sampleStore({
    loans: [
      sampleLoan({ id: 'loan_1', item: DVD, member: BEN, checkedOutOn: '2026-11-14', dueOn: '2026-11-21' }),
      sampleLoan({ id: 'loan_2', item: BOOK, member: ADA, checkedOutOn: '2026-11-04', dueOn: '2026-11-25' }),
    ],
  });
  const [five, one] = overdueNotices(store, TODAY);
  assert.match(five.body, /It is 5 days late\./);
  assert.match(one.body, /It is 1 day late\./);
});
